/* Fiche badminton 2027 : pourcentage de matchs gagnés ; poule de 6 : la tranche haute du degré 4 commence à 85 %. */
function badCol(C,deg){
 const p=pct(num(C.v.vic),num(C.v.mj));if(p==null)return {col:null,why:"Saisis les matchs gagnés et les matchs joués."};
 const top=deg===4&&num(C.v.poule)===6?85:80,col=p<30?0:p<60?1:p<top?2:3;
 return {col,why:String(p).replace(".",",")+" % de matchs gagnés : colonne « "+["< 30 %","30 à < 60 %","60 à < "+top+" %",top+" à 100 %"][col]+" »"+(top===85?" (poule de 6)":"")};
}
function pickCol(C){const p=pct(num(C.v.vic),num(C.v.mj));if(p==null)return {col:null,why:"Saisis les victoires et le nombre de matchs joués."};const col=p<25?0:p<50?1:p<75?2:3;return {col,why:String(p).replace(".",",")+" % de matchs gagnés : colonne « "+["< 25 %","25 à < 50 %","50 à < 75 %","75 à 100 %"][col]+" »"}}
